```ts
export interface NotifyConfig { botToken?: string; chatId?: string; }
export interface TurnNotification {
  projectId: string; projectName: string; sessionId: string;
  kind: 'done' | 'error'; status: string; detail?: string; // status='completed|parked|failed' or 'error'
}
export function telegramEnabled(cfg: NotifyConfig): boolean {
  return !!(cfg.botToken && cfg.chatId);
}
export async function sendTelegram(cfg: NotifyConfig, n: TurnNotification, fetchFn: typeof fetch = fetch): Promise<boolean> {
  if (!telegramEnabled(cfg)) return false;
  const icon = n.kind === 'error' || n.status === 'failed' ? '❌' : n.status === 'parked' ? '⏸' : '✅';
  // Plain text (NO parse_mode) so a project name with _ * ` [ can't break/inject Markdown.
  const text = `${icon} x056 · ${n.projectName}\n${n.kind === 'error' ? 'error: ' + (n.detail ?? 'failed') : 'turn ' + n.status}`;
  try {
    const res = await fetchFn(`https://api.telegram.org/bot${cfg.botToken}/sendMessage`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: cfg.chatId, text, disable_notification: false }),
    });
    return res.ok;
  } catch { return false; } // never let a notify failure surface into the turn
}
```
