const RESULT_MAX_CHARS = 12_000;
const DIFF_MAX_LINES = 300;

// tool_result.content is a string OR an array of blocks ({type:'text',text} | image).
function resultText(content: unknown): string {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  const parts: string[] = [];
  for (const b of content) {
    if (b && typeof b === 'object') {
      const t = (b as {type?:string}).type;
      if (t === 'text' && typeof (b as {text?:unknown}).text === 'string') parts.push((b as {text:string}).text);
      else if (t === 'image') parts.push('[image]');
    }
  }
  return parts.join('\n');
}
function capText(s: string): { text: string; truncated: boolean; bytes: number } {
  const bytes = s.length;
  return bytes > RESULT_MAX_CHARS ? { text: s.slice(0, RESULT_MAX_CHARS), truncated: true, bytes }
                                  : { text: s, truncated: false, bytes };
}
// Simple LCS line diff; caps output length.
function diffLines(oldS: string, newS: string): { lines: DiffLine[]; truncated: boolean } { /* LCS over line arrays → ' '/'+'/'-' rows */ }
function fullAddDiff(content: string): { lines: DiffLine[]; truncated: boolean } { /* every line as op '+', capped */ }
