function addAct(id, label, isSub) {
  var stick = atBottom();
  var wrap = document.createElement('div'); wrap.className = 'act' + (isSub ? ' sub' : '');
  var head = document.createElement('div'); head.className = 'act-head';
  var chev = icon('chevron','sm'); chev.classList.add('chev'); head.appendChild(chev);
  head.appendChild(icon(isSub ? 'sparkles' : 'terminal','sm'));
  var el = document.createElement('span'); el.className='el'; el.textContent = label; head.appendChild(el);
  var body = document.createElement('div'); body.className='act-body';
  head.addEventListener('click', function(){ if (wrap.classList.contains('expandable')) wrap.classList.toggle('open'); });
  wrap.appendChild(head); wrap.appendChild(body); chatEl.appendChild(wrap);
  var ref = { wrap: wrap, body: body }; if (id) actRows[id] = ref;
  if (stick) down(); return ref;
}
function setDetail(ref, detail, isError) {
  if (!ref) return;
  if (isError) ref.wrap.classList.add('err');
  if (!detail) { if (isError) ref.wrap.classList.add('expandable'); return; }
  ref.body.textContent = '';
  if (detail.kind === 'diff') ref.body.appendChild(renderDiff(detail));
  else { var pre = document.createElement('pre'); pre.className='act-out'; pre.textContent = detail.text + (detail.truncated ? '\n… (truncated)' : ''); ref.body.appendChild(pre); }
  ref.wrap.classList.add('expandable');
}
function renderDiff(detail){
  var pre = document.createElement('pre'); pre.className='diff';
  detail.lines.forEach(function(ln){ var r=document.createElement('div'); r.className='dl '+(ln.op==='+'?'add':ln.op==='-'?'del':'ctx'); r.textContent=ln.op+' '+ln.text; pre.appendChild(r); });
  if (detail.truncated){ var t=document.createElement('div'); t.className='dl ctx'; t.textContent='… (truncated)'; pre.appendChild(t); }
  return pre;
}
