```
private resumeInterrupted(): void {
  let markers: InflightMarker[];
  try { markers = this.readMarkers(); } catch { return; }
  if (markers.length === 0) return;
  // No accounts yet => can't resume; leave markers for a later boot.
  try { if (this.registry().list().length === 0) return; } catch { return; }
  const reg = this.projects();
  for (const m of markers) {
    try {
      if (this.runs.has(m.projectId)) continue;            // never double-resume
      const proj = reg.get(m.projectId);
      if (!proj || !proj.lastSessionId) { this.clearMarker(m.projectId); continue; } // project gone / no session
      if (m.attempts >= MAX_AUTO_RESUME_ATTEMPTS) {
        this.clearMarker(m.projectId);
        this.emit('turn_resume_abandoned', { projectId: m.projectId, sessionId: m.sessionId, attempts: m.attempts, reason: 'max auto-resume attempts reached' });
        continue;
      }
      const attempts = m.attempts + 1;                     // launch() will flush this to disk before spawn
      this.emit('turn_auto_resumed', { projectId: m.projectId, sessionId: m.sessionId, attempts });
      this.launch(m.projectId, m.sessionId, CONTINUE_PROMPT, m.cwd, true, { model: m.model, effort: m.effort }, attempts);
    } catch (err) {
      this.clearMarker(m.projectId);
      this.emit('turn_resume_abandoned', { projectId: m.projectId, sessionId: m.sessionId, attempts: m.attempts, reason: (err as Error).message });
    }
  }
}
```
Poison-loop bound: `launch()` calls `writeMarker(... attempts)` synchronously (fs write) before the async `runFn` spawns, so a container that crash-loops during resume records the incremented count on disk each boot; after MAX_AUTO_RESUME_ATTEMPTS the marker is retired with turn_resume_abandoned. A legitimate resume that finishes clears the marker in `.finally()`, resetting the count.

